import os
import random
from typing import List

# Generator for "arbitrary binary data" buffers intended to be valid payloads for:
# - wiringPiI2CWriteBlockData (size 0..64, any bytes)
# - wiringPiI2CRawWrite (size 0..64, any bytes)
# - wiringPiSPIDataRW / wiringPiSPIxDataRW (non-empty, preferably <=1024, any bytes)
# - ds1302clockWrite (consumed cyclically for 8 register bytes)
#
# Strategy:
# - Produce compact buffers (1..256 bytes) comprised of patterns that are meaningful for
#   exercising code paths while remaining valid: ramps, repeats, alternating patterns,
#   boundary-aligned lengths (0,1,2,3,4,7,8,15,16,31,32,63,64,128,256), and pseudo-random blocks.
# - Ensure buffers may include NULs and full 0..255 range.
# - Honor upper bound of 4096 bytes (we keep far below).
#
# The fuzzer stubs choose their own effective sizes: for I2C write-block/raw, they clamp size to 0..64
# and will resize/zero-extend the provided FUZZ_PARAM_STR() to at least that size. Providing at least
# 64 bytes ensures those calls always have sufficient data. SPI uses the full provided string up to 1024.
# ds1302clockWrite reads at least 8 bytes cyclically; any non-empty buffer works; we ensure >= 8 bytes often.

_BOUNDARY_LENGTHS: List[int] = [0,1,2,3,4,7,8,15,16,31,32,63,64,96,128,192,256]


def _pattern_repeat(byte: int, length: int) -> bytes:
    return bytes([byte]) * length


def _pattern_ramp(start: int, step: int, length: int) -> bytes:
    return bytes(((start + i * step) & 0xFF for i in range(length)))


def _pattern_alt(b0: int, b1: int, length: int) -> bytes:
    return bytes((b0 if (i & 1) == 0 else b1) for i in range(length))


def _pattern_blocks(values: List[int], block_size: int, repeats: int) -> bytes:
    block = bytes((v & 0xFF for v in values))
    block = (block * ((block_size + len(block) - 1) // len(block)))[:block_size]
    return block * repeats


def _pattern_random(rng: random.Random, length: int) -> bytes:
    return bytes(rng.randrange(0, 256) for _ in range(length))


def _choose_length(rng: random.Random) -> int:
    # Weight towards interesting boundary sizes, but allow random lengths too
    choices = []
    # Bias: include each boundary size multiple times
    for l in _BOUNDARY_LENGTHS:
        choices.extend([l] * 3)
    # Add random sizes in [1, 256]
    for _ in range(10):
        choices.append(rng.randint(1, 256))
    # Ensure we don't pick 0 too often; if 0, we'll still return at least 1 later when needed by SPI
    length = rng.choice(choices)
    return max(0, min(256, length))


def _build_buffer(rng: random.Random, length: int) -> bytes:
    # If length is zero, return empty (valid for I2C size=0 paths)
    if length == 0:
        return b""

    pattern_type = rng.randrange(0, 8)
    if pattern_type == 0:
        # All zeros
        return _pattern_repeat(0x00, length)
    elif pattern_type == 1:
        # All 0xFF
        return _pattern_repeat(0xFF, length)
    elif pattern_type == 2:
        # Alternating 0x00/0xFF
        return _pattern_alt(0x00, 0xFF, length)
    elif pattern_type == 3:
        # Alternating 0x55/0xAA
        return _pattern_alt(0x55, 0xAA, length)
    elif pattern_type == 4:
        # Linear ramp
        start = rng.randrange(0, 256)
        step = rng.choice([1, 2, 3, 5, 7, 13, 17, 31])
        return _pattern_ramp(start, step, length)
    elif pattern_type == 5:
        # Repeated short block (common register/value patterns)
        values = [rng.randrange(0, 256) for _ in range(rng.randint(2, 8))]
        block_size = rng.choice([2, 4, 8, 16])
        repeats = (length + block_size - 1) // block_size
        buf = _pattern_blocks(values, block_size, repeats)
        return buf[:length]
    elif pattern_type == 6:
        # Mixed segments: header + body + footer
        seg_lengths = [max(1, length // 8), max(1, length // 2), max(1, length // 8)]
        header = bytes([rng.randrange(0, 256) for _ in range(seg_lengths[0])])
        body = _pattern_ramp(rng.randrange(0, 256), rng.choice([1, 3, 5, 17]), seg_lengths[1])
        footer = _pattern_alt(rng.randrange(0, 256), rng.randrange(0, 256), seg_lengths[2])
        combined = (header + body + footer)
        if len(combined) < length:
            combined += _pattern_random(rng, length - len(combined))
        return combined[:length]
    else:
        # Pure random
        return _pattern_random(rng, length)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a base length with bias to boundaries; SPI wants non-empty; I2C can use up to 64
    length = _choose_length(rng)

    # Ensure we sometimes generate at least 64 bytes to satisfy I2C block upper bound
    if length < 64 and rng.random() < 0.6:
        # 60% chance to lift to one of {64, 96, 128}
        length = rng.choice([64, 96, 128])

    # Cap to 256 to keep buffers compact and within all stub bounds; SPI will accept up to 1024
    length = max(1, min(256, length))  # make non-empty for SPI paths

    buf = _build_buffer(rng, length)

    # Occasionally prepend a small "register-like" byte then payload, useful for some devices
    if rng.random() < 0.25 and len(buf) < 255:
        reg_like = bytes([rng.randrange(0, 256)])
        buf = reg_like + buf
        # still keep under 256
        buf = buf[:256]

    # Guarantee total size <= 4096 (we keep <=256 by construction)
    return buf
